SELECT id, conversation_id, user_id, role, content, intent, task_id,
       stream_interrupted, created_at
FROM ai_message
WHERE conversation_id = #{conversationId}
ORDER BY id ASC
LIMIT #{limit}

SELECT id, conversation_id, user_id, role, content, intent, task_id,
       stream_interrupted, created_at
FROM ai_message
WHERE conversation_id = #{conversationId}
  AND id > #{afterId}
ORDER BY id ASC
LIMIT #{limit}
